import { useState, useEffect, useMemo } from 'react'
import { ChevronDown, Loader2, Wrench, CheckCircle2, XCircle, Copy, Check, Terminal, FileText, Search, Braces } from 'lucide-react'
import { cn } from '@/lib/utils'
import type { ToolCallInfo } from '@/lib/api'
import { TodoBlock } from '@/components/chat/TodoBlock'
import type { TodoItem } from '@/components/chat/TodoBlock'

interface ToolCallLineProps {
  toolCall: ToolCallInfo
}

// --- 工具分类 ---

const BASH_TOOLS = ['bash', 'shell', 'run_command', 'execute', 'terminal', 'run_shell']
const FILE_TOOLS = ['read_file', 'read', 'write_file', 'write', 'edit', 'list_dir', 'file_read']
const SEARCH_TOOLS = ['search', 'grep', 'find', 'glob', 'search_code', 'search_files']

function isBashTool(name: string): boolean {
  const n = name.toLowerCase()
  return BASH_TOOLS.some(t => n.includes(t))
}

function isFileTool(name: string): boolean {
  const n = name.toLowerCase()
  return FILE_TOOLS.some(t => n.includes(t))
}

function isSearchTool(name: string): boolean {
  const n = name.toLowerCase()
  return SEARCH_TOOLS.some(t => n.includes(t))
}

function isJsonContent(s: string): boolean {
  const trimmed = s.trim()
  return (trimmed.startsWith('{') && trimmed.endsWith('}')) ||
    (trimmed.startsWith('[') && trimmed.endsWith(']'))
}

// --- 结果渲染组件 ---

/** 终端风格渲染（bash/shell 结果） */
function TerminalView({ content }: { content: string }) {
  return (
    <div className="rounded bg-[#1a1b26] p-3 font-mono text-xs text-gray-300 overflow-x-auto max-h-64 overflow-y-auto">
      <pre className="whitespace-pre-wrap break-all">{content}</pre>
    </div>
  )
}

/** 文件内容渲染（带行号） */
function FileView({ content }: { content: string }) {
  const lines = content.split('\n')
  return (
    <div className="rounded bg-muted/50 overflow-x-auto max-h-64 overflow-y-auto">
      <table className="w-full text-xs font-mono">
        <tbody>
          {lines.map((line, i) => (
            <tr key={i} className="hover:bg-muted/80">
              <td className="select-none pr-3 text-right text-muted-foreground/50 whitespace-nowrap align-top w-8">
                {i + 1}
              </td>
              <td className="whitespace-pre-wrap break-all">{line || ' '}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

/** JSON 内容渲染（格式化 + 语法高亮色） */
function JsonView({ content }: { content: string }) {
  const formatted = useMemo(() => {
    try {
      return JSON.stringify(JSON.parse(content), null, 2)
    } catch {
      return content
    }
  }, [content])

  return (
    <div className="rounded bg-muted/50 p-3 overflow-x-auto max-h-64 overflow-y-auto">
      <pre className="text-xs font-mono">
        <code>{formatted}</code>
      </pre>
    </div>
  )
}

/** 搜索结果渲染（匹配高亮） */
function SearchView({ content }: { content: string }) {
  const lines = content.split('\n')
  return (
    <div className="rounded bg-muted/50 overflow-x-auto max-h-64 overflow-y-auto">
      {lines.map((line, i) => {
        // 简单的 grep 风格：文件路径:行号:内容
        const match = line.match(/^(.+?):(\d+):(.*)$/)
        if (match) {
          return (
            <div key={i} className="flex text-xs font-mono hover:bg-muted/80 px-2 py-0.5">
              <span className="text-blue-500 shrink-0 mr-1">{match[1]}:{match[2]}</span>
              <span className="text-muted-foreground">{match[3]}</span>
            </div>
          )
        }
        return (
          <div key={i} className="text-xs font-mono px-2 py-0.5 hover:bg-muted/80 whitespace-pre-wrap">
            {line}
          </div>
        )
      })}
    </div>
  )
}

/** 通用预览（带行号 + 复制按钮） */
function PreView({ content }: { content: string }) {
  const [copied, setCopied] = useState(false)
  const lines = content.split('\n')

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(content)
      setCopied(true)
      setTimeout(() => setCopied(false), 1500)
    } catch { /* ignore */ }
  }

  return (
    <div className="relative rounded bg-muted/50 overflow-x-auto max-h-64 overflow-y-auto">
      <button
        type="button"
        onClick={handleCopy}
        className="absolute top-2 right-2 z-10 rounded p-1 text-muted-foreground/60 transition-colors hover:bg-muted hover:text-foreground"
        title="复制"
      >
        {copied ? <Check className="h-3 w-3 text-green-500" /> : <Copy className="h-3 w-3" />}
      </button>
      <table className="w-full text-xs font-mono">
        <tbody>
          {lines.map((line, i) => (
            <tr key={i} className="hover:bg-muted/80">
              <td className="select-none pr-3 text-right text-muted-foreground/50 whitespace-nowrap align-top w-8">
                {i + 1}
              </td>
              <td className="whitespace-pre-wrap break-all pr-8">{line || ' '}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

/** 根据工具类型和内容智能选择渲染方式 */
function renderToolResult(toolName: string, result: string) {
  if (isBashTool(toolName)) return <TerminalView content={result} />
  if (isFileTool(toolName)) return <FileView content={result} />
  if (isSearchTool(toolName)) return <SearchView content={result} />
  if (isJsonContent(result)) return <JsonView content={result} />
  return <PreView content={result} />
}

/** 获取工具类型图标 */
function getToolIcon(name: string) {
  if (isBashTool(name)) return <Terminal className="h-3.5 w-3.5 shrink-0 text-orange-500" />
  if (isFileTool(name)) return <FileText className="h-3.5 w-3.5 shrink-0 text-blue-500" />
  if (isSearchTool(name)) return <Search className="h-3.5 w-3.5 shrink-0 text-green-500" />
  if (name.toLowerCase().includes('json') || name.toLowerCase().includes('data')) return <Braces className="h-3.5 w-3.5 shrink-0 text-purple-500" />
  return <Wrench className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />
}

/**
 * 工具调用状态行（参考 deepseek-harness ToolCallTree）
 * - 显示工具名称 + 状态（运行中/完成/失败）
 * - 运行中时显示加载动画 + "正在执行..."
 * - 完成时显示耗时
 * - 可展开查看参数和结果（智能渲染）
 */
export function ToolCallLine({ toolCall }: ToolCallLineProps) {
  const [open, setOpen] = useState(false)
  const [elapsed, setElapsed] = useState<number | null>(null)

  // 特殊工具：todo_write 渲染为 TodoBlock（参照 deepseek-harness tool-todo）
  if (toolCall.name === 'todo_write' && toolCall.args?.todos) {
    const todos = toolCall.args.todos as TodoItem[]
    return <TodoBlock todos={todos} />
  }

  // 计算耗时
  useEffect(() => {
    if (toolCall.status === 'running' && toolCall.started_at) {
      const interval = setInterval(() => {
        setElapsed(Date.now() - new Date(toolCall.started_at!).getTime())
      }, 100)
      return () => clearInterval(interval)
    }
    if (toolCall.status !== 'running' && toolCall.started_at && toolCall.completed_at) {
      setElapsed(new Date(toolCall.completed_at).getTime() - new Date(toolCall.started_at).getTime())
    }
  }, [toolCall.status, toolCall.started_at, toolCall.completed_at])

  const formatDuration = (ms: number) => {
    if (ms < 1000) return `${ms}ms`
    return `${(ms / 1000).toFixed(1)}s`
  }

  const StatusIcon = () => {
    if (toolCall.status === 'running') {
      return <Loader2 className="h-3.5 w-3.5 animate-spin text-blue-500" />
    }
    if (toolCall.status === 'completed') {
      return <CheckCircle2 className="h-3.5 w-3.5 text-green-500" />
    }
    return <XCircle className="h-3.5 w-3.5 text-red-500" />
  }

  const statusText = () => {
    if (toolCall.status === 'running') return '正在执行...'
    if (toolCall.status === 'completed') return '已完成'
    return '失败'
  }

  return (
    <div className="w-full rounded-lg border border-border/40 bg-muted/20">
      <button
        type="button"
        onClick={() => setOpen(!open)}
        className="group flex w-full cursor-pointer items-center gap-2 px-3 py-2 text-sm transition-colors hover:bg-muted/40"
      >
        {getToolIcon(toolCall.name)}
        <StatusIcon />
        <span className="font-mono text-muted-foreground">{toolCall.name}</span>
        <span className="text-muted-foreground/70">·</span>
        <span className={cn(
          'text-xs',
          toolCall.status === 'running' && 'text-blue-500',
          toolCall.status === 'completed' && 'text-green-500',
          toolCall.status === 'error' && 'text-red-500'
        )}>
          {statusText()}
        </span>
        {elapsed !== null && toolCall.status !== 'running' && (
          <span className="ml-auto text-xs tabular-nums text-muted-foreground/70">
            {formatDuration(elapsed)}
          </span>
        )}
        <ChevronDown
          className={cn(
            'h-3.5 w-3.5 text-muted-foreground/70 transition-transform duration-150',
            open && 'rotate-180'
          )}
        />
      </button>
      {open && (
        <div className="border-t border-border/40 px-3 py-2 space-y-2">
          {toolCall.args && Object.keys(toolCall.args).length > 0 && (
            <div>
              <div className="text-xs font-medium text-muted-foreground mb-1">参数</div>
              <JsonView content={JSON.stringify(toolCall.args, null, 2)} />
            </div>
          )}
          {toolCall.result && (
            <div>
              <div className="text-xs font-medium text-muted-foreground mb-1">结果</div>
              {renderToolResult(toolCall.name, toolCall.result)}
            </div>
          )}
        </div>
      )}
    </div>
  )
}
